function hc(){return historyCopy[lang]}
function ext(url,label,cls='text-link'){return `<a class="${cls}" href="${url}" target="_blank" rel="noopener">${label} ↗</a>`}
function renderPress(){const c=hc();main.innerHTML=`<section class="history-page"><a class="breadcrumbs" href="#/">${c.back} / ${c.title}</a><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p class="history-lead">${c.lead}</p><article class="diplomatic-story"><div><img src="assets/real/real-top.jpg" alt="Victor Iermito · guitare" loading="lazy"><p class="image-note">${c.photo}</p></div><div><p class="eyebrow">2020 · FRANCE — ARGENTINA</p><h2>${c.story}</h2><p>${c.storyText}</p><p>${c.storyMore}</p>${ext('https://www.youtube.com/watch?v=5o00Eu-sVR8',c.watch,'custom-button')}</div></article><section class="recognition"><p class="eyebrow">${c.recognition}</p><div class="recognition-grid"><article><span class="award-year">2017</span><h3>${c.foundation}</h3><p>${c.foundationDetail}</p>${ext('https://www.fondationbanquepopulaire.fr/nos-laureats/',c.source)}</article><article><span class="award-year">2017</span><h3>${c.paris}</h3><p>${c.parisDetail}</p>${ext('https://www.bdmma.paris/wp-content/uploads/2019/06/RA_Ateliers_2017_print.pdf',c.source)}</article></div></section><section class="press-section"><h2>${c.press}</h2><div class="press-rows">${[['ln','LA NACION / LN+','05.02.2020'],['telam','Télam · La Insuperable','09.02.2020'],['time','Tiempo Argentino','11.02.2020'],['huarpe','Diario Huarpe','13.02.2020']].map(([id,name,date])=>`<article class="press-row"><span class="eyebrow">${date}</span><h3>${name}</h3><p>${c[id]}</p>${ext(pressLinks[id],c.read)}</article>`).join('')}</div><details class="press-archive"><summary>${c.archive}</summary><p class="image-note">${c.archiveNote}</p><ul>${[['Télam · Original','https://www.telam.com.ar/notas/202002/430458-victor-iermito-luthier-guitarra-alberto-fernandez-emmanuel-macron.html'],['Bagnara Calabra','https://www.bagnaracalabra.biz/curiosita/personaggi/victor-iermito/'],['Facebook · Vídeo','https://www.facebook.com/watch/?v=2710554972373119'],['YouTube · LA NACION','https://www.youtube.com/watch?v=5o00Eu-sVR8'],['Télam · X / Twitter','https://twitter.com/AgenciaTelam/status/1225147326588706817']].map(([name,url])=>`<li>${ext(url,name)}</li>`).join('')}</ul></details></section><section class="project-teaser"><p class="eyebrow">${c.projects}</p><h2>${c.voice}</h2><p>${c.voiceText}</p><span class="project-status">${c.pause}</span><a class="button" href="#/projects">${c.exploreProject} ↗</a></section></section>`;applyLanguage();}
function renderProjects(){const c=hc();main.innerHTML=`<section class="history-page"><a class="breadcrumbs" href="#/">${c.back} / ${c.projects}</a><p class="eyebrow">VICTOR IERMITO</p><h1>${c.projects}</h1><p class="history-lead">${c.projectIntro}</p><article class="voice-story"><div><p class="eyebrow">ECO · MUSIQUE · RENCONTRES</p><h2>${c.voice}</h2><span class="project-status">${c.pause}</span><p>${c.voiceText}</p><p>${c.voiceClosing}</p><a class="button" href="#/guitars/ECO">ECO ↗</a></div><img src="assets/real/session-1.jpg" alt="Victor Iermito · rosette" loading="lazy"></article><a class="quiet-link" href="#/press">← ${c.title}</a></section>`;applyLanguage();}
const homeBeforeHistory=renderHome;renderHome=function(){homeBeforeHistory();const c=hc();document.querySelector('.manifesto').insertAdjacentHTML('afterend',`<section class="section history-teaser"><div><p class="eyebrow">2020 · FRANCE — ARGENTINA</p><h2>${c.story}</h2><p>${c.storyText}</p><a class="button" href="#/press">${c.all} ↗</a></div><div class="history-distinction"><span>2017</span><p>${c.foundation}</p><hr><p>${c.paris}<br><small>${c.parisDetail}</small></p></div></section>`);document.querySelector('.contact').insertAdjacentHTML('beforebegin',`<section class="section home-project"><p class="eyebrow">${c.projects}</p><h2>${c.voice}</h2><p>${c.voiceClosing}</p><span class="project-status">${c.pause}</span><a class="button" href="#/projects">${c.exploreProject} ↗</a></section>`);};
